FUNCTION_BLOCK FB_Baliza
VAR_INPUT
    alarma : BOOL; // Variable de entrada que indica si hay una condición de alarma
END_VAR

VAR_OUTPUT
    lampara : BOOL; // Variable de salida que controla el estado de la lámpara
END_VAR

VAR
    temporizador : TON; // Temporizador para controlar el parpadeo
    estado_parpadeo : BOOL; // Estado interno para alternar el parpadeo
END_VAR

// Inicialización del temporizador
temporizador(IN := estado_parpadeo, PT := T#1S);

IF alarma THEN
    // Si hay alarma, activar el temporizador
    temporizador(IN := NOT temporizador.Q);

    // Alternar el estado de parpadeo cuando el temporizador termina
    IF temporizador.Q THEN
        estado_parpadeo := NOT estado_parpadeo;
    END_IF;

    // La lámpara sigue el estado de parpadeo
    lampara := estado_parpadeo;
ELSE
    // Si no hay alarma, apagar la lámpara y reiniciar el temporizador
    lampara := FALSE;
    estado_parpadeo := FALSE;
    temporizador(IN := FALSE);
END_IF;

END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_Baliza
VAR_INPUT
    alarma : BOOL; (* Condicion de alarma activa *)
END_VAR
VAR_OUTPUT
    lampara : BOOL; (* Lampara de baliza *)
END_VAR
VAR
    tOn  : TON; (* Temporizador fase encendida *)
    tOff : TON; (* Temporizador fase apagada *)
    parpadeo : BOOL; (* Estado interno de parpadeo *)
END_VAR

(* Sin alarma: lampara apagada y temporizadores reiniciados *)
IF NOT alarma THEN
    parpadeo := FALSE;
    tOn(IN := FALSE, PT := T#1S);
    tOff(IN := FALSE, PT := T#1S);
ELSE
    (* Fase encendida: activa tOn mientras parpadeo=TRUE *)
    tOn(IN := parpadeo, PT := T#1S);

    (* Fase apagada: activa tOff cuando tOn ha completado *)
    tOff(IN := tOn.Q, PT := T#1S);

    (* Al completar tOff, reinicia tOn para el siguiente ciclo *)
    IF tOff.Q THEN
        tOn(IN := FALSE, PT := T#1S);  (* Reinicia tOn *)
        tOff(IN := FALSE, PT := T#1S); (* Reinicia tOff *)
        parpadeo := TRUE;
    END_IF;

    (* Arranca el primer ciclo *)
    IF NOT parpadeo AND NOT tOn.Q AND NOT tOff.Q THEN
        parpadeo := TRUE;
    END_IF;
END_IF;

(* La lampara sigue el estado de parpadeo durante la fase encendida *)
lampara := alarma AND parpadeo AND NOT tOn.Q;
END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_Baliza
VAR_INPUT
    alarma : BOOL; (* Condicion de alarma activa *)
END_VAR
VAR_OUTPUT
    lampara : BOOL; (* Lampara de baliza *)
END_VAR
VAR
    tOn  : TON; (* Temporizador fase encendida *)
    tOff : TON; (* Temporizador fase apagada *)
    parpadeo : BOOL; (* Estado interno de parpadeo *)
END_VAR

(* Sin alarma: lampara apagada y temporizadores reiniciados *)
IF NOT alarma THEN
    parpadeo := FALSE;
    tOn(IN := FALSE, PT := T#1S);
    tOff(IN := FALSE, PT := T#1S);
ELSE
    (* Fase encendida: activa tOn mientras parpadeo=TRUE *)
    tOn(IN := parpadeo, PT := T#1S);
    (* Fase apagada: activa tOff cuando tOn ha completado *)
    tOff(IN := tOn.Q, PT := T#1S);

    (* Al completar fase apagada, reinicia tOn para nuevo ciclo *)
    IF tOff.Q THEN
        tOn(IN := FALSE, PT := T#1S);  (* Reinicia tOn *)
        tOff(IN := FALSE, PT := T#1S); (* Reinicia tOff *)
        parpadeo := TRUE;
    END_IF;

    (* Arranca el primer ciclo *)
    IF NOT parpadeo AND NOT tOn.Q AND NOT tOff.Q THEN
        parpadeo := TRUE;
    END_IF;
END_IF;

(* La lampara sigue el estado de parpadeo mientras tOn no haya terminado *)
lampara := alarma AND parpadeo AND NOT tOn.Q;
END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_Baliza
VAR_INPUT
    alarma : BOOL; // Variable de entrada que indica si hay una alarma
END_VAR

VAR_OUTPUT
    lampara : BOOL; // Variable de salida que controla el estado de la lámpara
END_VAR

VAR
    timer : TON; // Timer de conteo hacia arriba
    estado : BOOL; // Estado actual de la lámpara (encendida/apagada)
END_VAR

// Inicialización del timer
IF timer.Q = FALSE THEN
    timer(IN := TRUE, PT := T#1S);
END_IF;

// Lógica de la baliza
IF alarma THEN
    // Si hay alarma, la lámpara parpadea
    lampara := estado;
    IF timer.Q THEN
        // Cambia el estado de la lámpara al final del ciclo de 1 segundo
        estado := NOT estado;
        timer(IN := FALSE); // Reinicia el timer
        timer(IN := TRUE); // Reinicia el timer
    END_IF;
ELSE
    // Si no hay alarma, la lámpara permanece apagada
    lampara := FALSE;
END_IF;
END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_Baliza
VAR_INPUT
    alarma : BOOL; // Condicion de activacion de la alarma
END_VAR
VAR_OUTPUT
    lampara : BOOL; // Salida hacia la baliza luminosa
END_VAR
VAR
    ton_Encendido : TON; // Temporizador para el tiempo en estado encendido
    ton_Apagado : TON;   // Temporizador para el tiempo en estado apagado
END_VAR

// Generador de ciclo: ton_Encendido se activa con la alarma y se reinicia con ton_Apagado
ton_Encendido(IN := alarma AND NOT ton_Apagado.Q, PT := T#1S);

// ton_Apagado comienza a contar cuando ton_Encendido alcanza 1 segundo
ton_Apagado(IN := ton_Encendido.Q, PT := T#1S);

// La lampara se enciende si hay alarma, y se apaga durante el ciclo de ton_Apagado
lampara := alarma AND NOT ton_Encendido.Q;

END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_Baliza
VAR_INPUT
    alarma : BOOL; // Variable de entrada que indica si hay una alarma
END_VAR

VAR_OUTPUT
    lampara : BOOL; // Variable de salida que controla el estado de la lámpara
END_VAR

VAR
    estado : BOOL := FALSE; // Variable interna para controlar el estado de parpadeo
    timer : TON; // Timer para controlar el ciclo de parpadeo
END_VAR

// Configuración del timer para un ciclo de 1 segundo
timer(IN := TRUE, PT := T#1S);

// Lógica para controlar el estado de la lámpara
IF alarma THEN
    // Si hay alarma, la lámpara parpadea
    lampara := estado;
    // Cambiar el estado de la lámpara al final del ciclo del timer
    IF timer.Q THEN
        estado := NOT estado;
        timer(IN := FALSE); // Reiniciar el timer
    END_IF
ELSE
    // Si no hay alarma, la lámpara permanece apagada
    lampara := FALSE;
END_IF

FUNCTION_BLOCK FB_Baliza
VAR_INPUT
    alarma : BOOL; // Condición de alarma activa
END_VAR
VAR_OUTPUT
    lampara : BOOL; // Salida hacia la baliza luminosa
END_VAR
VAR
    Timer_ON : TON; // Temporizador para el tiempo de encendido (1s)
    Timer_OFF : TON; // Temporizador para el tiempo de apagado (1s)
END_VAR

// Temporizador que cuenta el tiempo que la lámpara permanece encendida
Timer_ON(IN := alarma AND NOT Timer_OFF.Q, PT := T#1S);

// Temporizador que cuenta el tiempo que la lámpara permanece apagada
Timer_OFF(IN := Timer_ON.Q, PT := T#1S);

// La lámpara enciende inmediatamente con la alarma y alterna su estado cada segundo
lampara := alarma AND NOT Timer_ON.Q;

END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_Baliza
VAR_INPUT
    alarma : BOOL; // Entrada que indica si hay una condición de alarma
END_VAR

VAR_OUTPUT
    lampara : BOOL; // Salida que controla el estado de la lámpara
END_VAR

VAR
    timerBlink : TON; // Temporizador para el parpadeo de la lámpara
    estadoParpadeo : BOOL; // Estado interno para el parpadeo
END_VAR

// Inicialización del temporizador
timerBlink(IN := estadoParpadeo, PT := T#1S);

// Lógica de control de la baliza
IF alarma THEN
    // Si hay alarma, alternar el estado de parpadeo cada segundo
    IF timerBlink.Q THEN
        estadoParpadeo := NOT estadoParpadeo;
        timerBlink(IN := FALSE); // Reiniciar el temporizador
    ELSE
        timerBlink(IN := TRUE); // Activar el temporizador
    END_IF;
    lampara := estadoParpadeo; // Actualizar el estado de la lámpara
ELSE
    // Si no hay alarma, la lámpara está apagada
    lampara := FALSE;
    estadoParpadeo := FALSE; // Reiniciar el estado de parpadeo
    timerBlink(IN := FALSE); // Asegurarse de que el temporizador esté desactivado
END_IF;
END_FUNCTION_BLOCK
